&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_disabling_the_audible_bell&quot;&gt;Disabling the Audible Bell&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_updating_kitty&quot;&gt;Updating Kitty&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_references&quot;&gt;References&lt;/a&gt;&lt;/li&gt;
