&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_step_2_the_gradle_plugin_transforms_the_knowledge_graph_into_plantuml&quot;&gt;Step 2: The Gradle plugin transforms the Knowledge Graph into PlantUML&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_pipeline_architecture&quot;&gt;Pipeline architecture&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_internal_components&quot;&gt;Internal components&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_rendering_rules&quot;&gt;Rendering rules&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_step_3_daily_usage&quot;&gt;Step 3: Daily usage&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_full_diagram&quot;&gt;Full diagram&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_filter_by_community&quot;&gt;Filter by community&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_filter_by_edge_type&quot;&gt;Filter by edge type&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_filter_by_node_type_and_confidence&quot;&gt;Filter by node type and confidence&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_custom_output_directory&quot;&gt;Custom output directory&lt;/a&gt;&lt;/li&gt;
