&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;modules&quot;&gt;Modules&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Modules allow the code to be organized into multiple files.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Example of rating:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-typescript&quot; data-lang=&quot;typescript&quot;&gt;// Dans un fichier math.ts
export const add = (a: number, b: number): number =&amp;gt; a + b;

// Dans un autre fichier
import { add } from &#39;./math&#39;;
let result = add(2, 3);&lt;/code&gt;&lt;/pre&gt;
